import style from "./TableFilters.module.scss";
import {TokenSelect} from "../../../_common/Filters/TokenSelect/TokenSelect";
import {ButtonGroup} from "../../../_common/Filters/ButtonGroup/ButtonGroup";
import {useState} from "react";
import {SelectOutlined} from "../../../_common/Filters/SelectOutlined/SelectOutlined";
import {clsx} from "clsx";
import {CheckBoxFilter} from "../../../_common/Filters/CheckBoxFilter/CheckBoxFilter";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import {ThemeEnum} from "../../../../store/app.store";
import {svgIcons} from "../../../../assets/svgIcons";
import {FiltersModal} from "./FiltersModal/FiltersModal";
import {newPairsValues, topValues, trendingValues} from "../../../../store/filters.store";
import {CustomizeFiltersModal} from "./CustomizeFiltersModal/CustomizeFiltersModal";

export const TableFilters = observer(() => {
    const {
        appStore: {theme},
        filtersStore: {
            top, setTop,
            trending, setTrending,
            gainers, setGainers,
            newPairs, setNewPairs,
            profile, setProfile,
            boosted, setBoosted,
            ads, setAds,
            setCustomizeFiltersModal,
        }
    } = useStore();

    const [filtersModal, setFiltersModal] = useState(false);

    const onCustomize = () => setCustomizeFiltersModal(true)

    return (
        <div className={style.tableFilters}>

            <FiltersModal filtersModal={filtersModal}
                          onClose={() => setFiltersModal(false)}
            />

            <CustomizeFiltersModal/>



            <div className={style.inner}>

                <div className={style.left}>

                    <TokenSelect/>

                    <SelectOutlined className={clsx(style.filter, style.onlyDesktop)}
                                    value={trending}
                                    values={trendingValues}
                                    setValue={(value) => setTrending(value)}
                                    buttonLabel="Trending"
                    />

                    <ButtonGroup className={clsx(style.filter, style.onlyDesktop)}
                                 label="Top"
                                 value={top}
                                 values={topValues}
                                 setValue={(_value) => setTop(_value)}
                    />

                    <SelectOutlined className={clsx(style.filter, style.onlyDesktop)}
                                    value={gainers}
                                    values={trendingValues}
                                    setValue={(value) => setGainers(value)}
                                    buttonLabel="Gainers"
                    />

                    <SelectOutlined className={clsx(style.filter, style.onlyDesktop)}
                                    value={newPairs}
                                    values={newPairsValues}
                                    setValue={(value) => setNewPairs(value)}
                                    buttonLabel="New Pairs"
                    />

                    <CheckBoxFilter className={clsx(style.filter, style.onlyDesktop)}
                                    label="Profile"
                                    checked={profile}
                                    setChecked={(_value) => setProfile(_value)}
                    />

                    <CheckBoxFilter className={clsx(style.filter, style.onlyDesktop)}
                                    label="Boosted"
                                    checked={boosted}
                                    setChecked={(_value) => setBoosted(_value)}
                    />

                    <CheckBoxFilter className={clsx(style.filter, style.onlyDesktop)}
                                    label="Ads"
                                    checked={ads}
                                    setChecked={(_value) => setAds(_value)}
                    />

                </div>

                <div className={style.left}>

                    <button className={clsx({
                        [style.resetFilterBtn]: true,
                        [style.resetFilterBtn_light]: theme === ThemeEnum.light,
                    }, style.onlyDesktop)}>
                        <span>Reset Filter</span>
                    </button>

                    <button className={clsx({
                        [style.customizeBtn]: true,
                        [style.customizeBtn_light]: theme === ThemeEnum.light,
                    }, style.onlyDesktop)}
                            onClick={onCustomize}
                    >
                        <span>Customize</span>
                        {svgIcons.filter_lines}
                    </button>

                    <button className={clsx({
                        [style.settingsBtn]: true,
                        [style.settingsBtn_light]: theme === ThemeEnum.light,
                    })}
                            onClick={() => setFiltersModal(true)}
                    >
                        {svgIcons.settings}
                    </button>

                </div>


            </div>
        </div>
    )
})