import {createBrowserRouter} from "react-router";
import {NewTokensPage} from "../B0_NewTokensPage/NewTokensPage";
import {AppLayout} from "./AppLayout";
import {Top100Page} from "../B1_Top100Page/Top100Page";
export const router = createBrowserRouter([
    {
        Component: AppLayout,
        children: [
            {
                path: "/",
                Component: NewTokensPage,
            },
            {
                path: "/top100",
                Component: Top100Page,
            },
        ]
    }
]);