import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import style from "./SelectOutlined.module.scss"
import {clsx} from "clsx";
import React, {useRef, useState} from "react";
import {ThemeEnum} from "../../../../store/app.store";
import {svgIcons} from "../../../../assets/svgIcons";
import Popover from "@mui/material/Popover";

interface ISelectOutlined {
    className?: string
    values: string[]
    value: string
    setValue: (value: string) => void
    buttonLabel: string
}

export const SelectOutlined = observer(({
                                            className,
                                            value,
                                            values,
                                            setValue,
                                            buttonLabel,
                                        }: ISelectOutlined) => {
    const {appStore: {theme}} = useStore();

    const [anchorEl, setAnchorEl] = useState<HTMLButtonElement | null>(null);
    const onOpen = (event: React.MouseEvent<HTMLButtonElement>) => setAnchorEl(event.currentTarget);

    const onClose = () => setAnchorEl(null);

    const open = Boolean(anchorEl);

    const ref = useRef<HTMLButtonElement>(null!)

    const width = ref?.current?.offsetWidth ? `${ref.current.offsetWidth}px` : "auto";

    return (
        <div className={clsx(style.selectOutlined, Boolean(className) && className)}>

            <button className={clsx({
                [style.btn]: true,
                [style.btn_open]: open,
                [style.btn_light]: theme === ThemeEnum.light,
            })}
                    onClick={onOpen}
                    ref={ref}
            >
                <p>
                    {buttonLabel} <span>({value})</span>
                </p>
                {svgIcons.arrow_up}
            </button>

            <Popover open={open}
                     anchorEl={anchorEl}
                     onClose={onClose}
                     anchorOrigin={{
                         vertical: 'bottom',
                         horizontal: 'left',
                     }}
                     sx={{
                         "& .MuiPaper-root": {
                             background: "transparent",
                             borderRadius: 0,
                             boxShadow: "none",
                         }
                     }}
            >
                <div className={style.dropdownWrapper}
                     style={{minWidth: width}}
                >
                    <div className={style.dropdown}>
                        {
                            values.map((_value, key) => (
                                <button key={key}
                                        className={style.item}
                                        onClick={() => {
                                            setValue(_value);
                                            onClose();
                                        }}
                                >
                                    <span>{_value}</span>
                                </button>
                            ))
                        }
                    </div>
                </div>

            </Popover>


        </div>
    )
})