import style from "./HowDoesProjectWork.module.scss"
import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../store/app.store";

export const HowDoesProjectWork = observer(() => {
    const {appStore: {theme}} = useStore();

    return (
        <div className={clsx({
            [style.howDoesProjectWork]: true,
            [style.howDoesProjectWork_light]: theme === ThemeEnum.light,
        })}>
            <div className={style.inner}>
                {
                    [
                        {
                            title: "How does Project work?",
                            text: `New cryptocurrency projects can be listed Applying Here. Once applied, they instantly become visible on the New Listings Page. After that, anyone can see and vote for the project. Get your community to vote on your project, because votes matter! Our ranking is simple: the highest votes is #1 on our website. The project will get exposure with all our visitors! Note on voting: Unique votes only count once for the "All Time" page, but can count every 24 hours on the "Today" page.`,
                        },
                        {
                            title: "Find the best new cryptocurrency projects",
                            text: `Did ever you wonder where people find the best new cryptocurrency projects, coins and tokens like Doge and Shiba Inu? They use websites like coinsniper.net. Cryptocurrency projects are listed here before CoinMarketCap, CoinGecko and major exchanges. Find the best crypto moonshots on our website. However: before investing always do your own research (DYOR)! Listing on coinsniper.net does NOT mean we endorse the project, they could be scams. Be careful with your investments.`,
                        },
                    ].map(({title, text}, key) => (
                       <div key={key}>
                           <p>{title}</p>
                           <p>{text}</p>
                       </div>
                    ))
                }
            </div>
        </div>
    )
})