import {action, makeObservable, observable} from "mobx";

export enum ThemeEnum {
    dark = "dark",
    light = "light"
}


export class AppStore {
    theme = ThemeEnum.dark
    isMenuOpen = false
    isNetworksOpen = false
    isCryptoCurrenciesOpen = false
    connectWalletModal = false

    constructor() {
        makeObservable(this,
            {
                theme: observable,
                isMenuOpen: observable,
                isNetworksOpen: observable,
                isCryptoCurrenciesOpen: observable,
                connectWalletModal: observable,

                setTheme: action.bound,
                setIsMenuOpen: action.bound,
                setIsNetworksOpen: action.bound,
                setIsCryptoCurrenciesOpen: action.bound,
                setConnectWalletModal: action.bound,
            }
        )
    }

    setTheme(theme: ThemeEnum) {
        this.theme = theme;
    }

    setIsMenuOpen(isMenuOpen: boolean) {
        this.isMenuOpen = isMenuOpen
    }

    setIsNetworksOpen(isNetworksOpen: boolean) {
        this.isNetworksOpen = isNetworksOpen
    }

    setIsCryptoCurrenciesOpen(isCryptoCurrenciesOpen: boolean) {
        this.isCryptoCurrenciesOpen = isCryptoCurrenciesOpen
    }

    setConnectWalletModal(connectWalletModal: boolean) {
        this.connectWalletModal = connectWalletModal
    }


}