import {ModalCustom} from "../../../../_common/ModalCustom/ModalCustom";
import {observer} from "mobx-react-lite";
import style from "./FiltersModal.module.scss";
import {clsx} from "clsx";
import {newPairsValues, topValues, trendingValues} from "../../../../../store/filters.store";
import {SelectOutlined} from "../../../../_common/Filters/SelectOutlined/SelectOutlined";
import {useStore} from "../../../../../store/rootStore";
import {ButtonGroup} from "../../../../_common/Filters/ButtonGroup/ButtonGroup";
import {CheckBoxFilter} from "../../../../_common/Filters/CheckBoxFilter/CheckBoxFilter";
import {ThemeEnum} from "../../../../../store/app.store";
import {svgIcons} from "../../../../../assets/svgIcons";

interface IFiltersModal {
    filtersModal: boolean
    onClose: () => void
}

export const FiltersModal = observer(({
                                          filtersModal,
                                          onClose
                                      }: IFiltersModal) => {
    const {
        appStore: {theme},
        filtersStore: {
            top, setTop,
            trending, setTrending,
            gainers, setGainers,
            newPairs, setNewPairs,
            profile, setProfile,
            boosted, setBoosted,
            ads, setAds,
            setCustomizeFiltersModal,
        }
    } = useStore();

    const onCustomize = () => setCustomizeFiltersModal(true)

    return (
        <ModalCustom open={filtersModal}
                     onClose={onClose}
                     contentClassName={style.filtersModal}
        >
            <>
                <p className={clsx({
                    [style.title]: true,
                    [style.title_light]: theme === ThemeEnum.light,
                })}>
                    Filters
                </p>

                <div className={style.filters}>
                    <SelectOutlined className={style.filter}
                                    value={trending}
                                    values={trendingValues}
                                    setValue={(value) => setTrending(value)}
                                    buttonLabel="Trending"
                    />

                    <ButtonGroup className={style.filter}
                                 label="Top"
                                 value={top}
                                 values={topValues}
                                 setValue={(_value) => setTop(_value)}
                    />

                    <SelectOutlined className={style.filter}
                                    value={gainers}
                                    values={trendingValues}
                                    setValue={(value) => setGainers(value)}
                                    buttonLabel="Gainers"
                    />

                    <SelectOutlined className={style.filter}
                                    value={newPairs}
                                    values={newPairsValues}
                                    setValue={(value) => setNewPairs(value)}
                                    buttonLabel="New Pairs"
                    />

                    <div className={clsx(style.filter, style.buttons)}>
                        <CheckBoxFilter label="Profile"
                                        checked={profile}
                                        setChecked={(_value) => setProfile(_value)}
                        />

                        <CheckBoxFilter label="Boosted"
                                        checked={boosted}
                                        setChecked={(_value) => setBoosted(_value)}
                        />

                        <CheckBoxFilter label="Ads"
                                        checked={ads}
                                        setChecked={(_value) => setAds(_value)}
                        />
                    </div>

                    <div className={clsx(style.filter, style.buttons)}>

                        <button className={clsx({
                            [style.resetFilterBtn]: true,
                            [style.resetFilterBtn_light]: theme === ThemeEnum.light,
                        })}>
                            <span>Reset Filter</span>
                        </button>

                        <button className={clsx({
                            [style.customizeBtn]: true,
                            [style.customizeBtn_light]: theme === ThemeEnum.light,
                        })}
                                onClick={onCustomize}
                        >
                            <span>Customize</span>
                            {svgIcons.filter_lines}
                        </button>
                    </div>
                </div>




            </>


        </ModalCustom>
    )
})