import style from "./ConnectWalletModal.module.scss";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import {ModalCustom} from "../../_common/ModalCustom/ModalCustom";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../store/app.store";
import phantom from "../../../assets/png/phantom.png";
import walletConnect from "../../../assets/png/walletConnect.png";
import solflare from "../../../assets/png/solflare.png";
import coinBase from "../../../assets/png/coinBase.png";
import trustWallet from "../../../assets/png/trustWallet.png";

export const ConnectWalletModal = observer(() => {
    const {appStore: {
        theme,
        connectWalletModal,
        setConnectWalletModal,
    }} = useStore();

    const onClose = () => setConnectWalletModal(false);

    return (
        <ModalCustom open={connectWalletModal}
                     onClose={() => onClose()}
        >
            <div className={clsx({
                [style.connectWalletModal]: true,
                [style.connectWalletModal_light]: theme === ThemeEnum.light,
            })}>
                <p className={style.cardTitle}>
                    Connect Your Wallet
                </p>

                <div className={style.wallets}>
                    {
                        [
                            {
                                icon: phantom,
                                label: "Phantom",
                                detected: true,
                            },
                            {
                                icon: walletConnect,
                                label: "WalletConnect",
                                detected: true,
                            },
                        ].map(({icon, label, detected}, key) => (
                            <div key={key}
                                 className={style.item}
                            >
                                <img src={icon} alt=""/>
                                <p className={style.label}>
                                    {label}
                                </p>
                                {detected && (
                                    <p className={style.detected}>detected</p>
                                )}
                            </div>
                        ))
                    }
                </div>

                <p className={style.cardlabel}>
                    Or choose other options
                </p>

                <div className={style.wallets}>
                    {
                        [
                            {
                                icon: solflare,
                                label: "Solflare",
                                detected: false,
                            },
                            {
                                icon: coinBase,
                                label: "CoinBase",
                                detected: false,
                            },
                            {
                                icon: trustWallet,
                                label: "TrustWallet",
                                detected: false,
                            },
                        ].map(({icon, label, detected}, key) => (
                            <div key={key}
                                 className={style.item}
                            >
                                <img src={icon} alt=""/>
                                <p className={style.label}>
                                    {label}
                                </p>
                                {detected && (
                                    <p className={style.detected}>detected</p>
                                )}
                            </div>
                        ))
                    }
                </div>

            </div>
        </ModalCustom>

    )
})