import {headerLabels} from "./data";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import style from "./Table.module.scss";
import {svgIcons} from "../../../../assets/svgIcons";
import logo from "../../../../assets/png/table_account.png";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../../store/app.store";
import {PaginationCustom} from "../../../_common/PaginationCustom/PaginationCustom";

export const Table = observer(() => {
    const {
        appStore: {theme},
    } = useStore();

    const [headerLabelFirst, ...restLabels] = headerLabels;

    return (
        <>
            <div className={clsx({
                [style.tableMobile]: true,
                [style.tableMobile_light]: theme === ThemeEnum.light,
            })}>

                <div className={style.tableMobileLeft}>

                    <div className={style.tableHeader}>
                        <div className={style.headerCell}>
                            <p>{headerLabelFirst}</p>
                        </div>
                    </div>

                    <div className={style.tableBody}>
                        {
                            Array.from(({length: 8}), (v, k) => k)
                                .map((_, key) => (
                                    <div key={key}
                                         className={style.bodyRow}
                                    >
                                        <div className={style.bodyCell}>
                                            {svgIcons.raydium_ray_logo}
                                            {svgIcons.binance_dark}
                                            <img src={logo} alt=""/>
                                            <p>VAL <span>/ SOL</span></p>
                                        </div>
                                    </div>
                                ))
                        }
                    </div>

                </div>

                <div className={style.tableMobileRight}>
                    <div className={style.tableMobileRightInner}>

                        <div className={style.tableHeader}>
                            {
                                restLabels.map((label, key) => (
                                    <div key={key}
                                         className={style.headerCell}
                                    >
                                        <p>{label}</p>
                                    </div>
                                ))
                            }
                        </div>

                        <div className={style.tableBody}>
                            {
                                Array.from(({length: 8}), (v, k) => k)
                                    .map((_, key) => (
                                        <div key={key}
                                             className={style.bodyRow}
                                        >

                                            <div className={style.bodyCell}>
                                                <p>$0.0001546</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>7h</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>56,497</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>$289K</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>51,228</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>-10.63%</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>-12.78%</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>-24,32%</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>-24,84%</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>$28K</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>$995</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>80%</p>
                                                <div className={style.progress}>
                                                    <div className={style.inner}
                                                         style={{width: "80%"}}
                                                    />
                                                </div>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>20%</p>
                                                <div className={style.progress}>
                                                    <div className={style.inner}
                                                         style={{width: "20%"}}
                                                    />
                                                </div>
                                            </div>


                                        </div>
                                    ))
                            }
                        </div>
                    </div>
                </div>

            </div>

            <div className={clsx({
                [style.tableDesktop]: true,
                [style.tableDesktop_light]: theme === ThemeEnum.light,
            })}>
                <div className={style.table_inner}>
                    <div className={style.tableHeader}>
                        {
                            headerLabels.map((label, key) => (
                                <div key={key}
                                     className={style.headerCell}
                                >
                                    <p>{label}</p>
                                </div>
                            ))
                        }
                    </div>

                    <div className={style.tableBody}>

                        <div className={style.tableBody}>
                            {
                                Array.from(({length: 8}), (v, k) => k)
                                    .map((_, key) => (
                                        <div key={key}
                                             className={style.bodyRow}
                                        >

                                            <div className={style.bodyCell}>
                                                <p>#1</p>
                                                {svgIcons.binance_dark}
                                                {svgIcons.binance_dark}
                                                <p className={style.label}>CPMM</p>
                                                <img src={logo} alt=""/>
                                                <p>Valensol <span>/ SOL Valensol</span></p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>$0.0001546</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>7h</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>56,497</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>$289K</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>51,228</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>-10.63%</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>-12.78%</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>-24,32%</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>-24,84%</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>$28K</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>$995</p>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>80%</p>
                                                <div className={style.progress}>
                                                    <div className={style.inner}
                                                         style={{width: "80%"}}
                                                    />
                                                </div>
                                            </div>

                                            <div className={style.bodyCell}>
                                                <p>20%</p>
                                                <div className={style.progress}>
                                                    <div className={style.inner}
                                                         style={{width: "20%"}}
                                                    />
                                                </div>
                                            </div>


                                        </div>
                                    ))
                            }
                        </div>


                    </div>
                </div>
            </div>

            <PaginationCustom count={40}/>

        </>
    )
})