import style from "./ButtonCustom.module.scss";
import {clsx} from "clsx";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import {ButtonHTMLAttributes, DetailedHTMLProps, ReactNode, useState} from "react";
import {ThemeEnum} from "../../../store/app.store";

export enum ButtonVariant {
    outlined = "outlined",
    contained = "contained",
    text = "text",
    yellow = "yellow",
    blue = "blue",
}

type ButtonCustomType = {
    className?: string
    variant?: ButtonVariant
    label?: string,
    icon?: ReactNode
} & DetailedHTMLProps<ButtonHTMLAttributes<HTMLButtonElement>, HTMLButtonElement>


export const ButtonCustom = observer(({
                                          className,
                                          variant = ButtonVariant.outlined,
                                          label,
                                          icon,
                                          ...buttonProps
                                      }: ButtonCustomType) => {
    const {appStore: {theme}} = useStore();

    const [mouseDown, setMouseDown] = useState(false);

    return (
        <button className={clsx({
            [style.buttonCustom]: true,
            [style.buttonCustom_icon]: !Boolean(label) && Boolean(icon),

            [style.buttonCustom_outlined]: variant === ButtonVariant.outlined,
            [style.buttonCustom_outlined_mouseDown]: variant === ButtonVariant.outlined && mouseDown,

            [style.buttonCustom_contained]: variant === ButtonVariant.contained,
            [style.buttonCustom_contained_mouseDown]: variant === ButtonVariant.contained && mouseDown,

            [style.buttonCustom_text]: variant === ButtonVariant.text,
            [style.buttonCustom_text_mouseDown]: variant === ButtonVariant.text && mouseDown,

            [style.buttonCustom_yellow]: variant === ButtonVariant.yellow,
            [style.buttonCustom_yellow_mouseDown]: variant === ButtonVariant.yellow && mouseDown,

            [style.buttonCustom_blue]: variant === ButtonVariant.blue,
            [style.buttonCustom_blue_mouseDown]: variant === ButtonVariant.blue && mouseDown,

            [style.buttonCustom_light]: theme === ThemeEnum.light,
        }, Boolean(className) && className)}
                onMouseDown={() => setMouseDown(true)}
                onMouseUp={() => setMouseDown(false)}
                {...buttonProps}
        >
            {
                Boolean(label) && (
                    <p>{label}</p>
                )
            }
            {
                Boolean(icon) && (
                    <>{icon}</>
                )
            }
        </button>
    )
})