import {ModalProps} from "@mui/material/Modal/Modal";
import {Modal} from "@mui/material";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import style from "./ModalCustom.module.scss";
import {clsx} from "clsx";
import {svgIcons} from "../../../assets/svgIcons";
import {ThemeEnum} from "../../../store/app.store";

interface IModalCustom extends ModalProps {
    contentClassName?: string
    onClose: () => void
}

export const ModalCustom = observer((props: IModalCustom) => {
    const {contentClassName, onClose, ...modalProps} = props;
    const {appStore: {theme}} = useStore();


    return (
        <Modal onClose={onClose}
               {...modalProps}
               sx={{
                   background: theme === ThemeEnum.dark ? "rgba(0,0,0,0.5)" : "rgba(255,255,255,0.5)",
                   backdropFilter: "blur(20px)",
                   display: "flex",
                   alignItems: "center",
                   justifyContent: "center",
               }}
        >
            <div className={clsx({
                [style.modalCustom]: true,
                [style.modalCustom_light]: theme === ThemeEnum.light,
            }, Boolean(contentClassName) && contentClassName)}>
                <button className={style.closeBtn}
                        onClick={onClose}
                >
                    {svgIcons.close}
                </button>
                {modalProps.children}
            </div>
        </Modal>
    )
})