import style from "./CheckBoxFilter.module.scss"
import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import {clsx} from "clsx";
import {svgIcons} from "../../../../assets/svgIcons";
import {ThemeEnum} from "../../../../store/app.store";

interface ICheckBoxFilter {
    className?: string
    label: string
    checked: boolean
    setChecked: (checked: boolean) => void
}

export const CheckBoxFilter = observer(({
                                            className,
                                            label,
                                            checked,
                                            setChecked,
                                        }: ICheckBoxFilter) => {
    const {appStore: {theme}} = useStore();

    return (
        <button className={clsx({
            [style.checkBoxFilter]: true,
            [style.checkBoxFilter_light]: theme === ThemeEnum.light,
        }, Boolean(className) && className)}
                onClick={() => setChecked(!checked)}
        >
            <p>{label}</p>
            <div className={clsx({
                [style.icon]: true,
                [style.icon_checked]: checked,
            })}>
                {svgIcons.check}
            </div>
        </button>

)
})