import style from "./SearchCoin.module.scss"
import {svgIcons} from "../../../../assets/svgIcons";
import {clsx} from "clsx";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import {ThemeEnum} from "../../../../store/app.store";

export const SearchCoin = observer(({className}: {className?: string}) => {
    const {appStore: {theme}} = useStore();

    return (
        <div className={clsx({
            [style.searchCoin]: true,
            [style.searchCoin_light]: theme === ThemeEnum.light,
        }, Boolean(className) && className)}>
            {svgIcons.search}
            <input type="text"
                   placeholder="Search coin"
            />
        </div>
    )
})