import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import style from "./ThemeSwitcher.module.scss";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../../store/app.store";
import {svgIcons} from "../../../../assets/svgIcons";

export const ThemeSwitcher = observer(({className}: {className?: string}) => {
    const {appStore: {theme, setTheme}} = useStore();
    const onClick = () => setTheme(theme === ThemeEnum.dark ? ThemeEnum.light : ThemeEnum.dark)

    return (
        <button className={clsx({
            [style.themeSwitcher]: true,
            [style.themeSwitcher_light]: theme === ThemeEnum.dark,
        }, Boolean(className) && className)}
              onClick={onClick}
        >
            {theme === ThemeEnum.dark ? svgIcons.darkMode : svgIcons.lightMode}
        </button>


    )
})