import {observer} from "mobx-react-lite";
import style from "./Panel.module.scss"
import {useStore} from "../../../store/rootStore";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../store/app.store";
import {Link} from "react-router";
import {svgIcons} from "../../../assets/svgIcons";
import {Menu} from "./Menu/Menu";
import {SearchCoin} from "./SearchCoin/SearchCoin";
import {ThemeSwitcher} from "./ThemeSwitcher/ThemeSwitcher";
import {Networks} from "./Networks/Networks";
import {CryptoCurrencies} from "./CryptoCurrencies/CryptoCurrencies";
import {ButtonCustom, ButtonVariant} from "../../_common/ButtonCustom/ButtonCustom";

export const Panel = observer(() => {
    const {
        appStore: {
            theme,
            setConnectWalletModal,
        }
    } = useStore();

    return (
        <div className={clsx({
            [style.panel]: true,
            [style.panel_light]: theme === ThemeEnum.light,
        })}>
            <div className={style.inner}>

                <div className={style.wrapper}>

                    <Link to="/"
                          className={style.logo}
                    >
                        {svgIcons.logo}
                    </Link>

                    <Menu className={style.menuDesktop}/>

                    <ThemeSwitcher className={style.themeSwitcherDesktop}/>

                    <SearchCoin className={style.searchCoin}/>

                    <Networks className={style.networks}/>

                    <CryptoCurrencies className={style.cryptoCurrencies}/>

                </div>

                <div className={style.wrapper}>
                    <button className={clsx({
                        [style.searchBtn]: true,
                        [style.searchBtn_light]: theme === ThemeEnum.light,
                    })}>
                        {svgIcons.search}
                    </button>

                    <ThemeSwitcher className={style.themeSwitcherMobile}/>

                    <Menu className={style.menuMobile}/>

                    <button className={clsx({
                        [style.cartBtn]: true,
                        [style.cartBtn_light]: theme === ThemeEnum.light,
                    })}>
                        <p>Cart</p>
                    </button>

                    <button className={clsx({
                        [style.submitCoinBtn]: true,
                        [style.submitCoinBtn_light]: theme === ThemeEnum.light,
                    })}>
                        <p>Submit Coin</p>
                        {svgIcons.plus}
                    </button>

                    <button className={clsx({
                        [style.gemSnifferBtn]: true,
                        [style.gemSnifferBtn_light]: theme === ThemeEnum.light,
                    })}>
                        <p>Gem Sniffer</p>
                        {svgIcons.dog_nose}
                    </button>

                    <button className={clsx({
                        [style.loginBtn]: true,
                        [style.loginBtn_light]: theme === ThemeEnum.light,
                    })}>
                        <p>Login</p>
                    </button>

                    <button className={clsx({
                        [style.createAccountBtn]: true,
                        [style.createAccountBtn_light]: theme === ThemeEnum.light,
                    })}>
                        <p>Create Account</p>
                        {svgIcons.arrow_up_right}
                    </button>

                    <button className={clsx({
                        [style.connectWalletBtn]: true,
                        [style.connectWalletBtn_light]: theme === ThemeEnum.light,
                    })}
                            onClick={() => setConnectWalletModal(true)}
                    >
                        <p>Connect Wallet</p>
                        {svgIcons.network}
                    </button>

                </div>


            </div>
        </div>
    )
})