import style from "./CryptoCurrencies.module.scss"

import {clsx} from "clsx";
import {Fade} from "@mui/material";
import {useRef} from "react";
import {svgIcons} from "../../../../assets/svgIcons";
import {useStore} from "../../../../store/rootStore";
import {observer} from "mobx-react-lite";
import {useOutsideButNotOnTargetClick} from "../../../../hooks/useOutsideButNotOnTargetClick";
import {ThemeEnum} from "../../../../store/app.store";


export const CryptoCurrencies = observer(({className}: { className?: string }) => {
    const {
        appStore: {
            theme,
            isCryptoCurrenciesOpen,
            setIsCryptoCurrenciesOpen
        }
    } = useStore();

    const ref = useRef<HTMLDivElement>(null!);
    const targetRef = useRef<HTMLButtonElement>(null!);
    useOutsideButNotOnTargetClick(ref, targetRef, () => setIsCryptoCurrenciesOpen(false));

    return (
        <div className={clsx(style.cryptoCurrencies, Boolean(className) && className)}>

            <button className={clsx({
                [style.btn]: true,
                [style.btn_open]: isCryptoCurrenciesOpen,
                [style.btn_light]: theme === ThemeEnum.light,
            })}
                    onClick={() => setIsCryptoCurrenciesOpen(!isCryptoCurrenciesOpen)}
                    ref={targetRef}
            >
                <p>All</p>
                {svgIcons.arrow_up}
            </button>

            <Fade in={isCryptoCurrenciesOpen}
                  onExiting={() => {

                  }}
            >
                <div className={style.dropdown}
                     ref={ref}
                >

                    <p className={style.label}>
                        Cryptocurrencies
                    </p>

                    <div className={style.list}>
                        {
                            [
                                {
                                    icon: svgIcons.crypto_currencies_new_tokens,
                                    label: "New Tokens",
                                },
                                {
                                    icon: svgIcons.crypto_currencies_top_100,
                                    label: "Top 100",
                                },
                                {
                                    icon: svgIcons.crypto_currencies_presales,
                                    label: "Presales",
                                },
                            ].map(({icon, label}, key) => (
                                <button key={key}
                                     className={style.item}
                                >
                                    <div>{icon}</div>
                                    <p>{label}</p>
                                </button>
                            ))
                        }
                    </div>

                </div>
            </Fade>
        </div>
    )
})