import style from "./Promoted.module.scss"
import {observer} from "mobx-react-lite";
import {clsx} from "clsx";
import {useStore} from "../../../store/rootStore";
import {ThemeEnum} from "../../../store/app.store";

export interface IPromotedItem {
    src: string
    name: string
}

interface IPromoted {
    className?: string
    items: IPromotedItem[]
}

export const Promoted = observer(({
                                      className,
                                      items,
                                  }: IPromoted) => {
    const {appStore: {theme}} = useStore();

    return (
        <div className={clsx({
            [style.promoted]: true,
            [style.promoted_light]: theme === ThemeEnum.light,
        }, Boolean(className) && className)}>
            <p className={style.title}>
                Promoted
            </p>
            <div className={style.items}>
                <div className={style.items_inner}>
                    {
                        items.map(({src, name}, key) => (
                            <div key={key}
                                 className={style.item}
                            >
                                <img src={src} alt=""/>
                                <p>{name}</p>
                            </div>
                        ))
                    }
                </div>

            </div>
        </div>
    )
})