import style from "./Widget.module.scss"
import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import {clsx} from "clsx";
import {ReactNode} from "react";
import {ThemeEnum} from "../../../../store/app.store";

interface IWidgetItem {
    src: string
    header: string
    description: string
    rightContent?: ReactNode
}

export interface IWidget {
    className?: string
    title: string
    titleIcon?: ReactNode
    items: IWidgetItem[]
    index: number
}

export const Widget = observer(({
                                    className,
                                    title,
                                    titleIcon,
                                    items,
                                    index
                                }: IWidget) => {
    const {appStore: {theme}} = useStore();

    return (
        <div className={clsx({
            [style.widget]: true,
            [style[`widget_${index}`]]: true,
            [style.widget_light]: theme === ThemeEnum.light,
        }, Boolean(className) && className)}>
            <div className={style.innerBase}>
                <div className={style.innerOpacity}>
                    <div className={style.header}>
                        <div>
                            <p>{title}</p>
                            {Boolean(titleIcon) && titleIcon}
                        </div>
                        <button className={style.showAllBtn}>
                            Show All
                        </button>
                    </div>

                    <div className={style.items}>
                        {
                            items.map(({
                                           src,
                                           header,
                                           description,
                                           rightContent,
                                       }, key) => (
                                <button key={key}
                                        className={style.item}
                                >
                                    <div className={style.item_left}>
                                        <img src={src} alt=""/>
                                        <div>
                                            <p>{header}</p>
                                            <p>{description}</p>
                                        </div>
                                    </div>
                                </button>
                            ))
                        }
                    </div>
                </div>
            </div>
        </div>
    )
})