import Pagination from "@mui/material/Pagination"
import PaginationItem from "@mui/material/PaginationItem"
import style from "./PaginationCustom.module.scss"
import {UsePaginationProps} from "@mui/material/usePagination/usePagination";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../store/app.store";
import {useMediaQuery} from "@mui/material";

export const PaginationCustom = observer((props: UsePaginationProps) => {
    const {
        appStore: {theme},
    } = useStore();

    const isMobile = useMediaQuery('(max-width: 1439px)');

    return (
        <div className={clsx({
            [style.paginationCustom]: true,
            [style.paginationCustom_light]: theme === ThemeEnum.light,
        })}>
            <div className={style.borderWrapper}>
                <Pagination className={style.pagination}
                            size={isMobile ? "small" : "medium"}
                            {...props}
                            renderItem={(item) => (
                                <PaginationItem {...item}
                                                sx={{
                                                    background: theme === ThemeEnum.dark ? "rgba(255, 255, 255, 0.05)" : "#eff2f5",
                                                    borderRadius: "11px",
                                                    color: theme === ThemeEnum.dark ? "#FFF" : "#000",
                                                    fontFamily: "Inter",
                                                    fontSize: "12px",
                                                    "&:hover": {
                                                        background: theme === ThemeEnum.dark ? "rgba(255, 255, 255, 0.5)" : "rgba(0, 0, 0, 0.5)",
                                                    },
                                                    "&.Mui-selected": {
                                                        background: theme === ThemeEnum.dark ? "#FFF" : "#010106",
                                                        color: theme === ThemeEnum.dark ? "#010106" : "#FFF",
                                                        "&:hover": {
                                                            background: theme === ThemeEnum.dark ? "#FFF" : "#010106",
                                                            color: theme === ThemeEnum.dark ? "#010106" : "#FFF",
                                                        },
                                                    },
                                                    "&.MuiPaginationItem-previousNext": {
                                                        background: "none",
                                                    },
                                                    "&.MuiPaginationItem-ellipsis": {
                                                        background: "#FFF",
                                                        color: "#FFF!important",
                                                    },
                                                }}

                                />
                            )
                            }
                />
            </div>

        </div>
    )
})