import style from "./AsideButton.module.scss"
import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import {ButtonHTMLAttributes, DetailedHTMLProps, ReactNode, useState} from "react";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../../store/app.store";
import {svgIcons} from "../../../../assets/svgIcons";

export type ButtonCustomType = {
    className?: string
    label: string,
    icon: ReactNode
} & DetailedHTMLProps<ButtonHTMLAttributes<HTMLButtonElement>, HTMLButtonElement>

export const AsideButton = observer(({
                                         className,
                                         label,
                                         icon,
                                         ...buttonProps
                                     }: ButtonCustomType) => {
    const {appStore: {theme}} = useStore();

    const [mouseDown, setMouseDown] = useState(false);

    return (
        <button className={clsx({
            [style.asideButton]: true,
            [style.asideButton_mouseDown]: mouseDown,
            [style.asideButton_light]: theme === ThemeEnum.light,
            [style.asideButton_light_mouseDown]: theme === ThemeEnum.light && mouseDown,
        }, Boolean(className) && className)}
                onMouseDown={() => setMouseDown(true)}
                onMouseUp={() => setMouseDown(false)}
                {...buttonProps}
        >
            <div className={style.left}>
                <div className={style.iconWrapper}>
                    {icon}
                </div>
                <p>{label}</p>
            </div>

            <div className={style.icon}>
                {svgIcons.arrow_right_light}
            </div>
        </button>
    )
})