import style from "./DropDownBlock.module.scss";
import {clsx} from "clsx";
import {Collapse} from "@mui/material";
import {FC, ReactNode} from "react";
import {svgIcons} from "../../../../../assets/svgIcons";
import {Link} from "react-router";

interface ILink {
    icon: ReactNode,
    label: string
    to: string
}

interface IDropDownBlock {
    label: string
    onHideClick: () => void
    show: boolean
    links: ILink[]
    onLinkClick: () => void
}

export const DropDownBlock: FC<IDropDownBlock> = ({
                                  label,
                                  onHideClick,
                                  show,
                                  links,
                                  onLinkClick
                              }) => {


    return (
        <div className={style.dropDownBlock}>
            <button className={clsx({
                [style.hideLinksBtn]: true,
                [style.hideLinksBtn_hide]: !show,
            })}
                    onClick={() => onHideClick()}
            >
                {svgIcons.arrow_up}
            </button>
            <p>{label}</p>
            <Collapse in={show}>
                <div className={style.links}>
                    {
                        links.map(({icon, label, to}, key) => (
                            <Link key={key}
                                  to={to}
                                  className={style.link}
                                  onClick={() => onLinkClick()}
                            >
                                <div className={style.iconWrapper}>
                                    {icon}
                                </div>
                                <p>{label}</p>
                            </Link>
                        ))
                    }
                </div>
            </Collapse>
        </div>
    )
}