import style from "./Networks.module.scss";
import {Fade} from "@mui/material";
import {useRef, useState} from "react";
import {networksList} from "./data";
import {clsx} from "clsx";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import {svgIcons} from "../../../../assets/svgIcons";
import {ThemeEnum} from "../../../../store/app.store";
import {useOutsideButNotOnTargetClick} from "../../../../hooks/useOutsideButNotOnTargetClick";

export const Networks = observer(({className}: {className?: string}) => {
    const {appStore: {theme, isNetworksOpen, setIsNetworksOpen}} = useStore();

    const [unselected, setUnselected] = useState(true);
    const [list, setList] = useState(networksList);

    const onSelectHandler = () => {
        setList(
            [
                ...list.map((item, index) => ({
                        ...item,
                        selected: unselected
                    })
                )
            ]
        )
        setUnselected(!unselected)
    }

    const ref = useRef<HTMLDivElement>(null!);
    const targetRef = useRef<HTMLButtonElement>(null!);
    useOutsideButNotOnTargetClick(ref, targetRef, () => setIsNetworksOpen(false));

    return (
        <div className={clsx(style.networks, Boolean(className) && className)}>

            <button className={clsx({
                [style.dropdownBtn]: true,
                [style.dropdownBtn_light]: theme === ThemeEnum.light,
            })}
                    onClick={() => setIsNetworksOpen(!isNetworksOpen)}
                    ref={targetRef}
            >
                {svgIcons.networks}
            </button>

            <Fade in={isNetworksOpen}
                  onExiting={() => {

                  }}
            >
                <div className={style.networksDropDown}
                     ref={ref}
                >

                    <div className={style.dropDownHeader}>
                        <p>
                            Networks
                        </p>
                        <button onClick={onSelectHandler}
                        >
                            <span>
                                {unselected ? "Select all" : "Unselect all"}
                            </span>
                        </button>
                    </div>

                    <div className={clsx({
                        [style.search]: true,
                        [style.search_light]: theme === ThemeEnum.light,
                    })}>
                        {svgIcons.search}
                        <input type="text"
                               placeholder="Search network"
                        />
                    </div>

                    <div className={style.networksList}>
                        {
                            list.map(({selected, icon, name}, key) => (
                                <button key={key}
                                        className={style.listItem}
                                        onClick={
                                            () => setList(
                                                [
                                                    ...list.map((item, index) => index === key
                                                        ? {
                                                            ...item,
                                                            selected: !item.selected
                                                        }
                                                        : item
                                                    )
                                                ]
                                            )
                                        }>
                                    <div className={style.listItemLeft}
                                    >
                                        <div className={style.leftIconWrapper}>
                                            {icon}
                                        </div>
                                        <p>
                                            {name}
                                        </p>
                                    </div>
                                    <div className={clsx({
                                        [style.checkbox]: true,
                                        [style.checkbox_selected]: selected,
                                    })}>
                                        {svgIcons.check}
                                    </div>
                                </button>
                            ))
                        }
                    </div>


                </div>
            </Fade>

        </div>
    )
})