import style from "./TwoBlocks.module.scss";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../store/app.store";
import {ButtonCustom, ButtonVariant} from "../../_common/ButtonCustom/ButtonCustom";
import four_icons from "../../../assets/png/four_icons.png";
import {svgIcons} from "../../../assets/svgIcons";

export const TwoBlocks = observer(() => {
    const {appStore: {theme}} = useStore();

    return (
        <div className={style.twoBlocks}>
            {
                [
                    {
                        title: "Your Favorite Coin Missing?",
                        description: "List your favorite coin now! Get your community to vote for your coin and gain exposure.",
                        button: {
                            label: "Submit Coin",
                            variant: ButtonVariant.yellow,
                            onClick: () => {
                            }
                        }
                    },
                    {
                        title: "View New Listings",
                        description: "Click the button below to view the New Listings! These coins were just submitted.",
                        button: {
                            label: "View New Listings",
                            variant: ButtonVariant.blue,
                            onClick: () => {
                            }
                        }
                    },
                ].map(({title, description, button}, key) => (
                    <div key={key}
                         className={clsx({
                             [style.block]: true,
                             [style.block_light]: theme === ThemeEnum.light,
                         })}
                    >
                        <div className={style.baseInner}>
                            <div className={style.opacityInner}>

                                {
                                    key === 1 && (
                                        <>
                                            {svgIcons.circle_gradient_0}
                                            {svgIcons.circle_gradient_2}
                                        </>
                                    )
                                }


                                {key === 0 && <img src={four_icons} alt=""/>}

                                <p className={style.title}>
                                    {title}
                                </p>
                                <p className={style.description}>
                                    {description}
                                </p>
                                <ButtonCustom {...button}
                                              className={style.btn}
                                />


                            </div>
                        </div>
                    </div>
                ))
            }
        </div>
    )
})