import {ModalCustom} from "../../../../_common/ModalCustom/ModalCustom";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../../../store/rootStore";
import style from "./CustomizeFiltersModal.module.scss"
import {svgIcons} from "../../../../../assets/svgIcons";
import {ButtonGroup} from "../../../../_common/Filters/ButtonGroup/ButtonGroup";
import {trendingValues} from "../../../../../store/filters.store";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../../../store/app.store";

export const CustomizeFiltersModal = observer(() => {
    const {
        appStore: {theme},
        filtersStore: {
            customizeFiltersModal, setCustomizeFiltersModal,
            time, setTime,
        }
    } = useStore();

    return (
        <ModalCustom open={customizeFiltersModal}
                     onClose={() => setCustomizeFiltersModal(false)}
                     contentClassName={clsx({
                         [style.customizeFiltersModal]: true,
                         [style.customizeFiltersModal_light]: theme === ThemeEnum.light,
                     })}
        >
            <>
                <p className={style.title}>
                    Customize Filters
                </p>

                <div className={style.body}>

                    <div className={style.inputGroupBlock}>
                        {
                            [
                                {
                                    groupLabel: "Liquidity",
                                    icon: svgIcons.dollar,
                                },
                                {
                                    groupLabel: "Market Cap",
                                    icon: svgIcons.dollar,
                                },
                                {
                                    groupLabel: "FDV",
                                    icon: svgIcons.dollar,
                                },
                                {
                                    groupLabel: "Pair Age (Hours)",
                                    icon: svgIcons.time,
                                },
                            ].map(({groupLabel, icon}, key) => (
                                <div key={key}
                                     className={style.inputGroup}
                                >
                                    <p className={style.label}>{groupLabel}</p>
                                    <div className={style.inputs}>
                                        <div className={style.inputWrapper}>
                                            {icon}
                                            <input type="text"
                                                   placeholder="Min"
                                            />

                                        </div>
                                        <div className={style.inputWrapper}>
                                            {icon}
                                            <input type="text"
                                                   placeholder="Max"
                                            />

                                        </div>
                                    </div>
                                </div>
                            ))
                        }
                    </div>

                    <ButtonGroup className={style.time}
                                 label="Time"
                                 value={time}
                                 values={trendingValues}
                                 setValue={(_value) => setTime(_value)}
                    />

                    <div className={style.inputGroupBlock}>
                        {
                            [
                                {
                                    groupLabel: "Transactions",
                                    icon: svgIcons.ticket,
                                },
                                {
                                    groupLabel: "Buys",
                                    icon: svgIcons.ticket,
                                },
                                {
                                    groupLabel: "Sells",
                                    icon: svgIcons.ticket,
                                },
                                {
                                    groupLabel: "Volume",
                                    icon: svgIcons.dollar,
                                },
                                {
                                    groupLabel: "Change",
                                    icon: svgIcons.dollar,
                                },
                            ].map(({groupLabel, icon}, key) => (
                                <div key={key}
                                     className={style.inputGroup}
                                >
                                    <p className={style.label}>{groupLabel}</p>
                                    <div className={style.inputs}>
                                        <div className={style.inputWrapper}>
                                            {icon}
                                            <input type="text"
                                                   placeholder="Min"
                                            />

                                        </div>
                                        <div className={style.inputWrapper}>
                                            {icon}
                                            <input type="text"
                                                   placeholder="Max"
                                            />
                                        </div>
                                    </div>
                                </div>
                            ))
                        }
                    </div>

                </div>

                <div className={style.footer}>

                    <button className={clsx({
                        [style.resetFilterBtn]: true,
                        [style.resetFilterBtn_light]: theme === ThemeEnum.light,
                    })}>
                        <span>Reset Filter</span>
                    </button>

                    <button className={clsx({
                        [style.applyFilterBtn]: true,
                        [style.applyFilterBtn_light]: theme === ThemeEnum.light,
                    })}

                    >
                        <p>Apply Filter</p>
                        {svgIcons.plus}
                    </button>

                </div>
            </>
        </ModalCustom>
    )
})