import style from "./AsideButtons.module.scss"
import {ReactNode} from "react";
import {AsideButton} from "./AsideButton/AsideButton";
import {svgIcons} from "../../../assets/svgIcons";

export const AsideButtons = () => {
    return (
        <div className={style.asideButtons}>
            {
                [
                    {
                        label: "Contact Us",
                        icon: svgIcons.contactUs,
                    },
                    {
                        label: "Blog",
                        icon: svgIcons.blog,
                    },
                    {
                        label: "Dictionary",
                        icon: svgIcons.dictionary,
                    },
                    {
                        label: "Advertising",
                        icon: svgIcons.advertising,
                    },
                    {
                        label: "Partners",
                        icon: svgIcons.partners,
                    },
                ].map((buttonProps, key) => (
                    <AsideButton key={key}
                                 {...buttonProps}
                                 className={style.btn}
                    />
                ))
            }
        </div>
    )
}