import style from "./Info.module.scss";
import {info} from "./data";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../store/app.store";
import {RunningStringItem} from "../../_common/RunningStringItem/RunningStringItem";

export const Info = observer(() => {
    const {appStore: {theme}} = useStore();

    return (
        <div className={style.info}>
            <div className={style.infoMobile}>
                <RunningStringItem item={<InfoItem theme={theme}/>}
                                   forward={false}
                                   count={2}
                                   duration={80}
                />
            </div>
            <div className={style.infoDesktop}>
                <InfoItem theme={theme}/>
            </div>
        </div>
    )
})

const InfoItem = ({theme}: {theme: ThemeEnum}) => {

    return (
        <div className={clsx({
            [style.infoItem]: true,
            [style.infoItem_light]: theme === ThemeEnum.light,
        })}>
            {
                info.map(({text, value}, key) => (
                   <p key={key}

                   >
                       <span>{text}:</span> {value}
                   </p>
                ))
            }
        </div>
    )
}