import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import style from "./Widgets.module.scss"
import {clsx} from "clsx";
import {IWidget, Widget} from "./Widget/Widget";
import {Swiper, SwiperSlide} from 'swiper/react';
import 'swiper/css';
import {ThemeEnum} from "../../../store/app.store";
import type {Swiper as SwiperClass} from "swiper/types";
import {useState} from "react";

interface IWidgets {
    className?: string
    widgets: IWidget[]
}

export const Widgets = observer(({
                                     className,
                                     widgets,
                                 }: IWidgets) => {
    const {appStore: {theme}} = useStore();
    const [index, setIndex] = useState(0)

    return (
        <div className={clsx(style.widgets, Boolean(className) && className)}>

            <Swiper className={style.widgetsMobile}
                    slidesPerView={1}
                    onSlideChange={(swiper: SwiperClass) => setIndex(swiper.realIndex)}
            >
                {
                    widgets.map((widget, key) =>
                        <SwiperSlide key={key}
                                     className={style.slide}
                        >
                            <Widget {...widget}/>
                        </SwiperSlide>

                    )
                }
            </Swiper>

            <div className={style.pagination}>
                {
                    [0,1,2,3].map(key => (
                        <div key={key}
                             className={clsx({
                                 [style.paginationItem]: true,
                                 [style.paginationItem_light]: theme === ThemeEnum.light,
                                 [style.paginationItem_selected]: key === index,
                                 [style.paginationItem_selected_light]: key === index && theme === ThemeEnum.light,
                             })}
                        />


                    ))
                }
            </div>

            <div className={style.widgetsDesktop}>
                <div className={style.widgetsDesktop_inner}>
                    {
                        widgets.map((widget, key) => <Widget key={key} {...widget}/>)
                    }
                </div>
            </div>
        </div>
    )
})