import {action, makeObservable, observable} from "mobx";
import {
    CustomizeFiltersModal
} from "../components/B0_NewTokensPage/TableSection/TableFilters/CustomizeFiltersModal/CustomizeFiltersModal";

export const topValues = ["Volume", "Txns"]
export const trendingValues = ["24H", "6H", "1H", "5M"];
export const newPairsValues = ["3D", "7D", "24H", "6H", "1H"];

export class FiltersStore {
    customizeFiltersModal = false
    top = topValues[0]
    trending = trendingValues[0]
    gainers = trendingValues[0]
    newPairs = newPairsValues[0]
    profile = false
    boosted = false
    ads = false
    time = trendingValues[0]

    constructor() {
        makeObservable(this,
            {
                customizeFiltersModal: observable,
                top: observable,
                trending: observable,
                gainers: observable,
                newPairs: observable,
                profile: observable,
                boosted: observable,
                ads: observable,
                time: observable,

                setCustomizeFiltersModal: action.bound,
                setTop: action.bound,
                setTrending: action.bound,
                setGainers: action.bound,
                setNewPairs: action.bound,
                setProfile: action.bound,
                setBoosted: action.bound,
                setAds: action.bound,
                setTime: action.bound,
            }
        )
    }

    setTop(top: string) {
        this.top = top;
    }

    setTrending(trending: string) {
        this.trending = trending;
    }

    setGainers(gainers: string) {
        this.gainers = gainers
    }

    setNewPairs(newPairs: string) {
        this.newPairs = newPairs
    }

    setProfile(profile: boolean) {
        this.profile = profile
    }

    setBoosted(boosted: boolean) {
        this.boosted = boosted
    }

    setAds(ads: boolean) {
        this.ads = ads
    }

    setCustomizeFiltersModal(customizeFiltersModal: boolean) {
        this.customizeFiltersModal = customizeFiltersModal
    }

    setTime(time: string) {
        this.time = time
    }
}