import style from "./Links.module.scss";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../store/app.store";
import {svgIcons} from "../../../assets/svgIcons";
import {Link} from "react-router";
import {links} from "./data";

export const Links = observer(() => {
    const {appStore: {theme}} = useStore();

    return (
        <div className={clsx({
            [style.links]: true,
            [style.links_light]: theme === ThemeEnum.light,
        })}>
            <div className={style.top}>
                <Link to="/"
                      className={style.logo}
                >
                    {svgIcons.logo}
                </Link>

                <nav className={style.items}>
                    {
                        links.map(({label, to, icon}, key) => (
                            <Link key={key}
                                  className={style.item}
                                  to={to}
                            >
                                <div>{icon}</div>
                                <p>{label}</p>
                            </Link>
                        ))
                    }
                </nav>
            </div>
            <div className={style.bottom}>
                <p>2024 bestpresales</p>
                <nav className={style.bottomLinks}>
                    {
                        [
                            {
                                label: "Cookie Statement",
                                to: "/cookieStatement",
                            },
                            {
                                label: "Terms & Conditions",
                                to: "/termsAndConditions",
                            },
                            {
                                label: "Privacy Policy",
                                to: "/privacyPolicy",
                            },
                        ].map(({label, to}, key) => (
                            <Link key={key}
                                  to={to}
                                  className={style.bottomLink}
                            >
                                <p>{label}</p>
                            </Link>
                        ))
                    }

                </nav>
            </div>

        </div>
    )
})