import style from "./ButtonGroup.module.scss";
import {observer} from "mobx-react-lite";
import {useStore} from "../../../../store/rootStore";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../../store/app.store";

interface IButtonGroup {
    className?: string
    label: string
    values: string[]
    value: string
    setValue: (value: string) => void
}

export const ButtonGroup = observer(({
                                         className,
                                         label,
                                         values,
                                         value,
                                         setValue,
                                     }: IButtonGroup) => {
    const {appStore: {theme}} = useStore();

    return (
        <div className={clsx({
            [style.buttonGroup]: true,
            [style.buttonGroup_light]: theme === ThemeEnum.light,
        }, Boolean(className) && className)}>

            <p>
                {label}
            </p>

            <div className={style.btns}>
                {
                    values.map((_value, key) => (
                        <button key={key}
                                className={clsx({
                                    [style.btn]: true,
                                    [style.btn_selected]: _value === value,
                                })}
                                onClick={() => setValue(_value)}
                        >
                            <span>{_value}</span>
                        </button>
                    ))
                }
            </div>
        </div>
    )
})