import style from "./Footer.module.scss"
import {TwoBlocks} from "./TwoBlocks/TwoBlocks";
import {HowDoesProjectWork} from "./HowDoesProjectWork/HowDoesProjectWork";
import {AsideButtons} from "./AsideButtons/AsideButtons";
import {Links} from "./Links/Links";

export const Footer = () => {
    return (
        <footer className={style.footer}>
            <div className={style.inner}>

                <div className={style.top}>
                    <div className={style.top_left}>
                        <TwoBlocks/>
                        <HowDoesProjectWork/>
                    </div>
                    <AsideButtons/>
                </div>
                <Links/>



            </div>
        </footer>
    )
}