import {observer} from "mobx-react-lite";
import {useStore} from "../../../store/rootStore";
import style from "./Banner.module.scss";
import {clsx} from "clsx";
import {ThemeEnum} from "../../../store/app.store";
import {Link} from "react-router";

interface IBanner {
    className?: string
    src: string
}

export const Banner = observer(({className, src}: IBanner) => {
    const {appStore: {theme}} = useStore();

    return (
        <div className={clsx({
            [style.banner]: true,
            [style.banner_light]: theme === ThemeEnum.light,
        }, Boolean(className) && className)}>

            <div className={style.inner}>

                <img src={src} alt=""/>

                <p>
                    Do you want to be here? <Link to="/"> Contact us</Link>
                </p>

            </div>

        </div>
    )
})