import {Banner} from "../_common/Banner/Banner";
import banner_0 from "../../assets/png/banner_0.png";
import banner_1 from "../../assets/png/banner_1.png";
import style from "./NewTokensPage.module.scss";
import {Promoted} from "../_common/Promoted/Promoted";
import {promotedItems, widgets} from "./data";
import {Widgets} from "../_common/Widgets/Widgets";
import {TableSection} from "./TableSection/TableSection";

export const NewTokensPage =() => {
    return (
        <div className={style.newTokensPage}>
            <Banner src={banner_0}/>
            <Promoted className={style.promoted}
                      items={promotedItems}
            />
            <Widgets className={style.widgets}
                     widgets={widgets}
            />
            <TableSection/>
            <Banner src={banner_1} className={style.banner}/>
        </div>
    )
}